                    }
                },
                "required": [
                    "name",
                    "value"
                ],
                "type": "object"
            },
            "type": "array"
        }
    },
    "required": [
        "domainUUID",
        "unitNr",
        "timestamp",
        "tx"
    ],
    "type": "object"
