    "version": "0.2",
    "definitions": {
        "color": {
            "type": "string",
            "pattern": "^#[0-9a-fA-F]{6}([0-9a-fA-F]{2})?$",
            "title": "Color",
            "description": "Color in #RRGGBB format",
            "examples": [
                "#123abc"
            ]
        }
    },
    "type": "object",
    "$schema": "http://json-schema.org/draft-07/schema#",
    "required": [
        "name",
        "dark",
        "author",
        "ui"
    ],
    "properties": {
        "name": {
            "type": "string",
            "title": "Theme name",
            "description": "Theme name",
            "default": "",
            "examples": [
                "My Brand New Theme"
            ]
        },
        "dark": {
            "type": "boolean",
            "title": "Dark theme",
            "description": "If 'true' then Darcula theme will be used as the base for modification, otherwise Light theme will be used.",
            "default": false,
            "examples": [
                true
            ]
        },
        "author": {
            "type": "string",
            "title": "Theme author",
            "description": "The author of the theme",
            "default": "",
            "examples": [
                "John Doe"
            ]
        },
        "editorScheme": {
            "type": "string",
            "title": "Path to the editor schema xml file starting with '/'",
            "default": "",
            "pattern": "^/",
            "examples": [
                "/editorScheme.xml"
            ]
        },
        "ui": {
            "type": "object"
        },
        "background": {
            "type": "object",
            "required": [
                "image"
            ],
            "title": "Background image",
            "description": "Background image for entire window",
            "properties": {
                "image": {
                    "type": "string",
                    "title": "Path to the background image",
                    "description": "Path to the background image starting with '/'",
                    "default": "",
                    "examples": [
                        "/background.jpg"
                    ]
                },
                "transparency": {
                    "type": "integer",
